output_text:
[
  {
    "id": "take_entry_cart",
    "text": "A shopper must take the entry cart from the cart station before continuing the trip.",
    "abstraction": {
      "state_properties": {
        "entry_cart_station": {
          "and": [
            "at(1,5)",
            "cartAt(1,5)"
          ]
        }
      },
      "events": {
        "take_entry_cart_event": {
          "pre": {
            "and": [
              "entry_cart_station",
              "PICKUP_CART"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "take_entry_cart_event"
    }
  },
  {
    "id": "cart_required_for_items",
    "text": "Items may not be picked up unless the shopper currently has the cart.",
    "abstraction": {
      "state_properties": {
        "cartless": {
          "not": "hasCart"
        }
      },
      "events": {
        "pickup_item_without_cart": {
          "pre": {
            "and": [
              "cartless",
              "PICKUP_ITEM"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "pickup_item_without_cart"
    }
  },
  {
    "id": "no_hand_carrying_while_walking",
    "text": "A shopper should not walk around the store while carrying an item by hand.",
    "abstraction": {
      "state_properties": {
        "carrying_by_hand": "handFull"
      },
      "events": {
        "move_with_hand_item": {
          "pre": {
            "and": [
              "carrying_by_hand",
              {
                "or": [
                  "N",
                  "S",
                  "E",
                  "W",
                  "MOVE"
                ]
              }
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "move_with_hand_item"
    }
  },
  {
    "id": "return_cart_after_item_pickup",
    "text": "After any item has been collected using the cart, the cart must eventually be returned to the northwest return point.",
    "abstraction": {
      "state_properties": {
        "with_cart": "hasCart",
        "cart_return_point": "at(0,1)"
      },
      "events": {
        "cart_item_pickup": {
          "pre": {
            "and": [
              "with_cart",
              "PICKUP_ITEM"
            ]
          },
          "post": null
        },
        "return_cart_northwest": {
          "pre": {
            "and": [
              "cart_return_point",
              "with_cart",
              "LEAVE_CART"
            ]
          },
          "post": "cartAt(0,1)"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "cart_item_pickup",
      "discharge": "return_cart_northwest"
    }
  },
  {
    "id": "cart_only_left_at_return",
    "text": "A cart may be put down only at the designated northwest cart-return cell.",
    "abstraction": {
      "state_properties": {
        "not_at_cart_return": {
          "not": "at(0,1)"
        }
      },
      "events": {
        "leave_cart_elsewhere": {
          "pre": {
            "and": [
              "LEAVE_CART",
              "not_at_cart_return"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "leave_cart_elsewhere"
    }
  },
  {
    "id": "exit_without_cart",
    "text": "A shopper is not allowed to leave the supermarket while still holding or pushing the cart.",
    "abstraction": {
      "state_properties": {
        "with_cart": "hasCart"
      },
      "events": {
        "exit_with_cart": {
          "pre": {
            "and": [
              "with_cart",
              "EXIT"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "exit_with_cart"
    }
  },
  {
    "id": "no_interactions_after_cart_return",
    "text": "Once the cart has been returned, the shopper should not perform further object interactions before exiting.",
    "abstraction": {
      "state_properties": {
        "cart_already_returned": "cartAt(0,1)"
      },
      "events": {
        "interaction_after_return": {
          "pre": {
            "and": [
              "cart_already_returned",
              "INTERACT"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "interaction_after_return"
    }
  },
  {
    "id": "monotone_exit_after_return",
    "text": "After returning the cart, the shopper should proceed toward the exit without moving north or west.",
    "abstraction": {
      "state_properties": {
        "post_cart_return_phase": "cartAt(0,1)"
      },
      "events": {
        "backtrack_after_cart_return": {
          "pre": {
            "and": [
              "post_cart_return_phase",
              {
                "or": [
                  "N",
                  "W"
                ]
              }
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "backtrack_after_cart_return"
    }
  }
]
